function renderPagination(q, type, status, genres, page, totalPages, sort = "popular", year = 0) {
  const qs = new URLSearchParams();
  if (q)
    qs.set("q", q);
  if (type)
    qs.set("type", type);
  if (status)
    qs.set("status", status);
  if (sort !== "trending")
    qs.set("sort", sort);
  if (year)
    qs.set("year", String(year));
  let base = `/browse?${qs.toString()}`;
  for (const g of genres)
    base += `&genres[]=${g}`;
  const baseUrl = base + "&page=";
  const start = Math.max(1, page - 2);
  const end = Math.min(totalPages, page + 2);
  let out = '<div class="pagination">';
  if (page > 1)
    out += `<a href="${baseUrl}${page - 1}">\u2039</a>`;
  for (let i = start; i <= end; i++) {
    out += i === page ? `<span class="current">${i}</span>` : `<a href="${baseUrl}${i}">${i}</a>`;
  }
  if (page < totalPages)
    out += `<a href="${baseUrl}${page + 1}">\u203A</a>`;
  out += "</div>";
  return out;
}
