// Use requestIdleCallback so the loader gets dismissed first
function afterPaint(fn) {
  if (window.requestIdleCallback) {
    requestIdleCallback(fn, { timeout: 3000 });
  } else {
    setTimeout(fn, 100);
  }
}

function startAnimePageLoaders() {
  afterPaint(() => {
    lazyLoadEpisodes();
    lazyLoadCharacters();
    lazyLoadRelated();
    lazyLoadVideos();
    lazyLoadPictures();
  });
}

