        // Safari can parse HLS natively; other browsers use the Senshi HLS pipeline.
        if(window.SenshiPlayer && window.SenshiPlayer.loadWithSubs){
          window.SenshiPlayer.loadWithSubs(source.url, source.subtitles);
        }
