        try { if(window.SenshiPlayer && window.SenshiPlayer.destroy) window.SenshiPlayer.destroy(); }catch(e){}
        try { video.pause(); }catch(e){}
        try { video.srcObject=null; }catch(e){}
        video.removeAttribute('src');
