function luluTrackGroup(track) {
  const label = String(track?.label || track?.name || "").trim().toLowerCase();
  const lang = String(track?.lang || "").trim().toLowerCase();
  const text = label + " " + lang;
  if (/^hi$|^hin$|hindi|हिन्दी|हिंदी/.test(text))
    return "hindi";
  if (/^en$|^eng$|english/.test(text))
    return "dub";
  if (/^ja$|^jpn$|japanese|日本語|\\b(sub|subtitle|original)\\b/.test(text))
    return "sub";
  return track?.default ? "sub" : "multi";
}
