function parseLuluTracks(row) {
  try {
    const v = JSON.parse(row.audio_tracks || "[]");
    if (!Array.isArray(v))
      return [];
    const seen = {};
    return v.map((t) => {
      const group3 = luluTrackGroup(t);
      const label = String(t?.label || t?.name || "").trim().toLowerCase();
      const lang = String(t?.lang || "").trim().toLowerCase();
      const base = [label, lang, group3].join("|");
      const occurrence = seen[base] || 0;
      seen[base] = occurrence + 1;
      return { ...t, group: group3, key: [label, lang, group3, occurrence].join("|") };
    });
  } catch {
    return [];
  }
}
