function parseDurationSeconds(durationStr) {
  if (!durationStr)
    return 0;
  const minMatch = durationStr.match(/(\d+)\s*min/i);
  if (minMatch)
    return parseInt(minMatch[1], 10) * 60;
  const hrMatch = durationStr.match(/(\d+)\s*hr/i);
  if (hrMatch)
    return parseInt(hrMatch[1], 10) * 3600;
  return 0;
}
