function renderUserListPagination(siteUrl, username, filterStatus, page, pages, total) {
  let baseUrl = `${siteUrl}/u/${h(username)}?`;
  if (filterStatus)
    baseUrl += `status=${encodeURIComponent(filterStatus)}&`;
  baseUrl += "page=";
  const rangeStart = Math.max(1, page - 2);
  const rangeEnd = Math.min(pages, page + 2);
  let out = '<div class="pagination">';
  if (page > 1)
    out += `<a href="${baseUrl}${page - 1}">\u2039</a>`;
  if (rangeStart > 1) {
    out += `<a href="${baseUrl}1">1</a>`;
    if (rangeStart > 2)
      out += `<span style="border:none;background:none;width:auto;padding:0 4px;">\u2026</span>`;
  }
  for (let i = rangeStart; i <= rangeEnd; i++)
    out += `<a href="${baseUrl}${i}" class="${i === page ? "current" : ""}">${i}</a>`;
  if (rangeEnd < pages) {
    if (rangeEnd < pages - 1)
      out += `<span style="border:none;background:none;width:auto;padding:0 4px;">\u2026</span>`;
    out += `<a href="${baseUrl}${pages}">${pages}</a>`;
  }
  if (page < pages)
    out += `<a href="${baseUrl}${page + 1}">\u203A</a>`;
  out += "</div>";
  out += `<p class="text-center text-muted" style="font-size:0.82rem;margin-top:-1rem;">Page ${page} of ${pages} \xB7 ${total.toLocaleString("en-US")} total entries</p>`;
  return out;
}
