async function buildAdminCtx(c) {
  const db = new Db(c.env.DB);
  const lifetime2 = Number(c.env.SESSION_LIFETIME_SECONDS ?? 86400);
  const session = await Session.load(c, db, lifetime2);
  const auth = new Auth(db, session, c.env, c.req.header("cf-connecting-ip") ?? "unknown");
  if (!auth.requireAdmin())
    return null;
  const impersonateData = session.data.impersonate_owner ?? null;
  return {
    db,
    session,
    lifetime: lifetime2,
    auth,
    userId: session.user_id,
    isOwner: auth.isOwner(),
    impersonating: impersonateData ? { username: session.data.username ?? "" } : null
  };
}
