async function resolveIpCountry(kv, ip) {
  if (!ip || ip === "unknown")
    return "";
  const cacheKey = `geo_${ip}`;
  const cached = await kv.get(cacheKey);
  if (cached !== null)
    return cached;
  try {
    const res = await fetch(`http://ip-api.com/json/${ip}?fields=country,countryCode`);
    if (res.ok) {
      const d = await res.json();
      if (d.country) {
        const code = d.countryCode ?? "";
        let flag = "";
        if (code.length === 2) {
          const cp1 = 127462 + code.charCodeAt(0) - 65;
          const cp2 = 127462 + code.charCodeAt(1) - 65;
          flag = String.fromCodePoint(cp1, cp2);
        }
        const result = `${flag} ${d.country}`.trim();
        await kv.put(cacheKey, result, { expirationTtl: 86400 * 30 });
        return result;
      }
    }
  } catch {
  }
  return ip;
}
