adminMiscSmallRoutes.post("/admin/ip_country.php", async (c) => {
  const db = new Db(c.env.DB);
  const lifetime2 = Number(c.env.SESSION_LIFETIME_SECONDS ?? 86400);
  const session = await Session.load(c, db, lifetime2);
  const auth = new Auth(db, session, c.env, c.req.header("cf-connecting-ip") ?? "unknown");
  if (!auth.isAdmin()) {
    await session.save(c, lifetime2);
    return c.json({}, 403);
  }
  const body = await c.req.json().catch(() => null);
  if (!Array.isArray(body) || body.length === 0) {
    await session.save(c, lifetime2);
    return c.json([]);
  }
  const ipRegex = /^(?:\d{1,3}\.){3}\d{1,3}$|^[0-9a-fA-F:]+$/;
  const ips = body.slice(0, 100).filter((ip) => ipRegex.test(ip));
  if (ips.length === 0) {
    await session.save(c, lifetime2);
    return c.json([]);
  }
  try {
    const res = await fetch("http://ip-api.com/batch?fields=query,country,countryCode", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(ips.map((ip) => ({ query: ip })))
    });
    const result = res.ok ? await res.json() : [];
    await session.save(c, lifetime2);
    return c.json(result);
  } catch {
    await session.save(c, lifetime2);
    return c.json([]);
  }
});

