adminLuluStreamRoutes.get("/admin/lulustream_cdn_test.php", async (c) => {
  const ctx3 = await buildAdminCtx(c);
  if (!ctx3)
    return c.json({ error: "Forbidden" }, 403);
  const { session, lifetime: lifetime2 } = ctx3;
  const embedUrl = c.req.query("url");
  if (!embedUrl) {
    await session.save(c, lifetime2);
    return c.json({ error: "Missing ?url=" }, 400);
  }
  try {
    const resolved = await resolveLuluStream(embedUrl);
    const master = await probe(resolved.video.url, resolved.referer);
    let variant = null;
    let audio = null;
    let segment = null;
    let hls = { mediaUris: [], variantUris: [] };
    if (master.ok && master.looksLikeHls) {
      hls = extractHlsUris(master.manifestLines.join("\n"), master.finalUrl);
      if (!hls.variantUris.length && master.nonTagUris?.length) {
        hls.variantUris = master.nonTagUris.filter((uri) => /\.m3u8(?:\?|$)/i.test(uri)).map((uri) => withInheritedQuery(uri, master.finalUrl));
      }
      const variantUrl = hls.variantUris[0];
      if (variantUrl) {
        variant = await probe(variantUrl, resolved.referer);
        if (variant.ok && variant.looksLikeHls) {
          const segmentUrl = extractFirstSegment(variant.manifestLines?.join("\n") || variant.bodyPreview, variant.finalUrl);
          if (segmentUrl)
            segment = await probeSegment(segmentUrl, resolved.referer);
        }
      }
      const audioUrl = hls.mediaUris[0];
      if (audioUrl)
        audio = await probe(audioUrl, resolved.referer);
    }
    await session.save(c, lifetime2);
    return c.json({
      success: true,
      provider: "lulustream",
      embedUrl: resolved.embedUrl,
      title: resolved.title,
      cdnHost: new URL(resolved.video.url).hostname,
      master,
      hls,
      variant,
      audio,
      segment,
      extractedTracks: {
        audio: resolved.audio.length,
        subtitles: resolved.subtitles.length
      },
      diagnosis: !master.ok ? "Master playlist request failed; CDN access is the first failure point." : !master.looksLikeHls ? "Master request succeeded but did not return an HLS playlist." : !hls.variantUris.length ? "Master has no #EXT-X-STREAM-INF video variant; inspect the extracted audio playlists." : !variant?.ok ? "Master is reachable, but the first video variant playlist failed." : !segment?.ok ? "Video variant is reachable, but the first media segment failed." : "Master \u2192 video variant \u2192 media segment all respond successfully from the Worker."
    });
  } catch (e) {
    await session.save(c, lifetime2);
    return c.json({
      success: false,
      provider: "lulustream",
      embedUrl,
      error: e instanceof Error ? e.message : String(e)
    }, 502);
  }
});
